/**
 * Customer Support AI Agent
 *
 * This agent handles customer support conversations with the following capabilities:
 * - Answer questions about the Promus product
 * - Help with feature requests and bug reports
 * - Provide guidance on setup and configuration
 * - Maintain conversation context across messages
 */
export const supportAgent = new Agent(components.agent, {
	name: 'Coda',

	// Language model configuration
	languageModel: getSupportLanguageModel(),

	// System instructions defining agent behavior
	instructions: `You are Coda, the support agent for Promus — an AI-powered todo list that grows 8 arms. Promus connects to your professional tools (Google, LinkedIn, WhatsApp, Outlook) and uses AI agents to research, draft, and execute your tasks in the background.

Keep answers short. WhatsApp style. No walls of text.

What Promus does:
- Users add todos in plain language ("Follow up with Marc about the proposal")
- An AI agent analyzes the task, writes Unipile SDK code, and executes it
- The agent researches, drafts emails, sends messages, connects on LinkedIn — then asks for confirmation before executing
- Users stay in control: the agent prepares, the human approves

How it works technically:
- Kanban board: drag-and-drop tasks between Todo, In Progress, Done
- Connected accounts: users link Google (Gmail & Calendar), LinkedIn, WhatsApp via Unipile OAuth in Settings → Connections
- Single agent architecture: Claude Opus generates and executes Unipile SDK code directly in a sandboxed Node VM
- Everything traced via W&B Weave for observability

Common questions you can answer:
- How to connect accounts (Settings → Connections → Connect Account)
- What integrations are supported (Google (Gmail & Calendar), Outlook, LinkedIn, WhatsApp, Instagram, Telegram)
- How tasks are processed (add todo → agent plans → agent executes → user confirms)
- Privacy: credentials stay server-side, sandbox is isolated, user approves every action
- Pricing and plan differences

If someone asks about something you don't know, say so and offer to connect them with the team.`,

	// Call settings for the language model
	callSettings: {
		temperature: 0.7 // Balanced between creativity and consistency
	},

	// Context management for conversation memory
	contextOptions: {
		recentMessages: 20 // Include last 20 messages for context
	},

	// Prevent infinite loops
	maxSteps: 5
});

import { createOpenAI } from '@ai-sdk/openai';
import { openrouter } from '@openrouter/ai-sdk-provider';
import { internal } from '../_generated/api';
import { CODEX_API_ENDPOINT } from '../openai';

export function getSupportLanguageModel(): any {
	return openrouter('qwen/qwen3-vl-30b-a3b-thinking');
}

/**
 * Get the task agent language model for a specific user.
 * Uses the user's connected ChatGPT account (OAuth access token).
 * Throws if the user has not connected their OpenAI account.
 */
export async function getTaskLanguageModelForUser(
	ctx: { runAction: (fn: any, args: any) => Promise<any> },
	userId: string
): Promise<any> {
	const result = await ctx.runAction(internal.openai.getValidAccessToken, { userId });
	if (!result) {
		throw new Error(
			'OpenAI account not connected. Connect your ChatGPT account in Settings → Connections to use the task agent.'
		);
	}
	return getOpenAILanguageModel(result.accessToken, result.accountId, 'gpt-5.4');
}

/**
 * Create an OpenAI language model that uses the ChatGPT Codex API endpoint.
 * Uses the user's OAuth access token (from their ChatGPT Plus/Pro subscription).
 */
export function getOpenAILanguageModel(
	accessToken: string,
	accountId?: string,
	modelId: string = 'gpt-5.4'
): any {
	const openai = createOpenAI({
		apiKey: 'codex-oauth', // Placeholder — overridden by custom fetch
		fetch: async (input, init) => {
			const headers = new Headers(init?.headers);

			// Remove placeholder API key and set OAuth token
			headers.delete('authorization');
			headers.delete('Authorization');
			headers.set('Authorization', `Bearer ${accessToken}`);

			// Set ChatGPT account ID for org subscriptions
			if (accountId) {
				headers.set('ChatGPT-Account-Id', accountId);
			}

			// Rewrite URL to Codex endpoint
			const parsed =
				input instanceof URL ? input : new URL(typeof input === 'string' ? input : input.url);
			const isCodexRequest =
				parsed.pathname.includes('/v1/responses') || parsed.pathname.includes('/chat/completions');
			const url = isCodexRequest ? new URL(CODEX_API_ENDPOINT) : parsed;

			// Codex Responses API requires `instructions` field.
			// The AI SDK puts system prompts in `input` as role:"system" messages,
			// so extract them and set as `instructions` for the Codex endpoint.
			let body = init?.body;
			if (isCodexRequest && typeof body === 'string') {
				try {
					const json = JSON.parse(body);
					// Codex requires store=false
					json.store = false;
					if (Array.isArray(json.input)) {
						// Extract system/developer messages into `instructions` field
						if (!json.instructions) {
							const systemMessages: string[] = [];
							json.input = json.input.filter((item: Record<string, unknown>) => {
								if (item.role === 'system' || item.role === 'developer') {
									systemMessages.push(item.content as string);
									return false;
								}
								return true;
							});
							if (systemMessages.length > 0) {
								json.instructions = systemMessages.join('\n\n');
							}
						}
						// Strip item_reference entries — with store=false the API
						// cannot resolve references to items from previous responses.
						// The actual content (function_call, function_call_output) is
						// already present inline in the input array.
						json.input = json.input.filter(
							(item: Record<string, unknown>) => item.type !== 'item_reference'
						);
					}
					body = JSON.stringify(json);
				} catch {
					// If parsing fails, send as-is
				}
			}

			const response = await fetch(url, { ...init, body, headers });

			// Log raw Codex API response for debugging finishReason issues
			if (isCodexRequest) {
				const cloned = response.clone();
				cloned
					.text()
					.then((text) => {
						// Extract status from SSE stream or JSON response
						const statusMatch = text.match(/"status"\s*:\s*"([^"]+)"/);
						const incompleteMatch = text.match(/"incomplete_details"\s*:\s*\{[^}]*\}/);
						const errorMatch = text.match(/"error"\s*:\s*\{[^}]*\}/);
						console.log(
							`[codex-debug] status=${statusMatch?.[1] ?? 'unknown'}`,
							incompleteMatch ? `incomplete=${incompleteMatch[0]}` : '',
							errorMatch ? `error=${errorMatch[0]}` : '',
							`bodyLen=${text.length}`
						);
					})
					.catch(() => {});
			}

			return response;
		}
	});

	return openai.responses(modelId);
}

import { describe, expect, it } from 'vitest';

import { executeWebSearch } from './webSearch';

function jsonResponse(status: number, body: unknown): Response {
	return {
		ok: status >= 200 && status < 300,
		status,
		json: async () => body,
		text: async () => JSON.stringify(body)
	} as unknown as Response;
}

/** Build a fetch that returns each queued response (or throws a queued error) in order. */
function makeFetch(queue: Array<Response | Error>): {
	impl: typeof fetch;
	state: { calls: number };
} {
	const state = { calls: 0 };
	const impl = (async () => {
		const next = queue[state.calls];
		state.calls += 1;
		if (next === undefined) throw new Error('unexpected extra fetch call');
		// DOMException does not extend Error in Node, so check it explicitly.
		if (next instanceof Error || next instanceof DOMException) throw next;
		return next;
	}) as unknown as typeof fetch;
	return { impl, state };
}

const noopSleep = async () => {};

describe('executeWebSearch', () => {
	it('maps results and enforces the total content budget', async () => {
		const { impl, state } = makeFetch([
			jsonResponse(200, {
				results: [
					{
						title: 'First',
						url: 'https://first.example',
						publishedDate: '2026-01-15T10:00:00.000Z',
						text: 'x'.repeat(15_000)
					},
					{ title: 'Second', url: 'https://second.example', text: 'hello' }
				]
			})
		]);

		const result = await executeWebSearch(
			{ query: 'budget test', count: 5 },
			{ fetchImpl: impl, apiKey: 'key', sleep: noopSleep }
		);

		if (!result.success) throw new Error(`expected success, got ${result.error}`);
		expect(result.query).toBe('budget test');
		// First result eats the whole 12k budget, so the second is dropped.
		expect(result.results).toHaveLength(1);
		expect(result.results[0]).toEqual({
			title: 'First',
			url: 'https://first.example',
			published: '2026-01-15',
			content: 'x'.repeat(12_000)
		});
		expect(state.calls).toBe(1);
	});

	it('falls back to the url when a title is missing and omits an absent date', async () => {
		const { impl } = makeFetch([
			jsonResponse(200, {
				results: [
					{ url: 'https://no-title.example', text: 'body a' },
					{ title: 'Has Title', url: 'https://b.example', text: 'body b' }
				]
			})
		]);

		const result = await executeWebSearch(
			{ query: 'shape' },
			{ fetchImpl: impl, apiKey: 'key', sleep: noopSleep }
		);

		if (!result.success) throw new Error(`expected success, got ${result.error}`);
		expect(result.results).toHaveLength(2);
		expect(result.results[0]).toEqual({
			title: 'https://no-title.example',
			url: 'https://no-title.example',
			published: undefined,
			content: 'body a'
		});
		expect(result.results[1].title).toBe('Has Title');
	});

	it('returns not_configured without touching the network when no key is set', async () => {
		const { impl, state } = makeFetch([]);
		const prev = process.env.EXA_API_KEY;
		delete process.env.EXA_API_KEY;
		try {
			const result = await executeWebSearch(
				{ query: 'no key' },
				{ fetchImpl: impl, sleep: noopSleep }
			);
			expect(result).toEqual({ success: false, error: 'not_configured' });
			expect(state.calls).toBe(0);
		} finally {
			if (prev !== undefined) process.env.EXA_API_KEY = prev;
		}
	});

	it('retries once after a 429 and succeeds', async () => {
		const { impl, state } = makeFetch([
			jsonResponse(429, { error: 'rate limited' }),
			jsonResponse(200, { results: [{ url: 'https://ok.example', text: 'done' }] })
		]);
		const sleeps: number[] = [];

		const result = await executeWebSearch(
			{ query: 'retry' },
			{ fetchImpl: impl, apiKey: 'key', sleep: async (ms) => void sleeps.push(ms) }
		);

		if (!result.success) throw new Error(`expected success, got ${result.error}`);
		expect(result.results).toHaveLength(1);
		expect(state.calls).toBe(2);
		expect(sleeps).toEqual([2_000]);
	});

	it('gives up with rate_limited after two 429 responses', async () => {
		const { impl, state } = makeFetch([
			jsonResponse(429, { error: 'rate limited' }),
			jsonResponse(429, { error: 'rate limited' })
		]);

		const result = await executeWebSearch(
			{ query: 'still limited' },
			{ fetchImpl: impl, apiKey: 'key', sleep: noopSleep }
		);

		expect(result).toEqual({ success: false, error: 'rate_limited' });
		expect(state.calls).toBe(2);
	});

	it('maps a 400 to invalid_query without retrying', async () => {
		const { impl, state } = makeFetch([jsonResponse(400, { error: 'bad request' })]);

		const result = await executeWebSearch(
			{ query: 'bad' },
			{ fetchImpl: impl, apiKey: 'key', sleep: noopSleep }
		);

		expect(result).toEqual({ success: false, error: 'invalid_query' });
		expect(state.calls).toBe(1);
	});

	it('returns timeout immediately without retrying on a TimeoutError', async () => {
		const { impl, state } = makeFetch([new DOMException('timeout', 'TimeoutError')]);

		const result = await executeWebSearch(
			{ query: 'slow' },
			{ fetchImpl: impl, apiKey: 'key', sleep: noopSleep }
		);

		expect(result).toEqual({ success: false, error: 'timeout' });
		expect(state.calls).toBe(1);
	});
});

